const NAMED_COLORS: Readonly<Record<string, string>> = {
  black: "#000000",
  brown: "#936439",
  red: "#FF263C",
  orange: "#FF6700",
  yellow: "#FF9800",
  green: "#00C972",
  cyan: "#00BCA6",
  blue: "#1084FE",
  violet: "#9159FE",
  magenta: "#FF309B",
  gray: "#777777",
};

// The desktop caller selects unset characters from the original agent ID, not its display name.
// These are the 0.18.0 u4e/sle defaults; the two color seed XORs cancel (aOt = 1).
export function resolveGrokBotAvatarDefaults(source: {
  id: string;
  avatarShape?: string;
  avatarColor?: string;
}): { avatarShape: string; avatarColor: string } {
  let hash = 2166136261;
  for (let index = 0; index < source.id.length; index++) {
    hash = Math.imul(hash ^ source.id.charCodeAt(index), 16777619);
  }
  let shapeHash = Math.imul(hash ^ (hash >>> 16), 73244475);
  shapeHash = Math.imul(shapeHash ^ (shapeHash >>> 13), 3266489909);
  shapeHash = (shapeHash ^ (shapeHash >>> 16)) >>> 0;
  const shapes = ["blob", "pebble", "squircle", "tablet", "wedge", "hex", "cloud", "teardrop"];
  const colorSeed = ((hash >>> 0) + 1831565813) | 0;
  let colorHash = Math.imul(colorSeed ^ (colorSeed >>> 15), 1 | colorSeed);
  colorHash = (colorHash + Math.imul(colorHash ^ (colorHash >>> 7), 61 | colorHash)) ^ colorHash;
  const colorFraction = ((colorHash ^ (colorHash >>> 14)) >>> 0) / 4294967296;
  const colors = [
    "brown",
    "red",
    "orange",
    "yellow",
    "green",
    "cyan",
    "blue",
    "violet",
    "magenta",
    "gray",
  ];
  return {
    avatarShape: source.avatarShape || shapes[shapeHash % shapes.length] || "blob",
    avatarColor: source.avatarColor || colors[Math.floor(colorFraction * colors.length)] || "black",
  };
}

