export function renderGrokBotAvatar(
  shape: string | undefined,
  color: string | undefined,
): {
  svg: string;
  warnings: GrokBotImportWarning[];
} {
  const warnings: GrokBotImportWarning[] = [];
  const appMark = shape && Object.hasOwn(APP_MARKS, shape) ? APP_MARKS[shape] : undefined;
  const knownShape = shape === "hex" || appMark !== undefined;
  if (!knownShape) {
    warnings.push({
      code: "avatar_shape_unsupported",
      message: `Grok avatar shape ${JSON.stringify(shape ?? "unspecified")} is not supported. A circular placeholder was imported; choose a replacement avatar.`,
    });
  }
  let fill = color && Object.hasOwn(NAMED_COLORS, color) ? NAMED_COLORS[color] : color;
  if (!fill || !/^#[a-f0-9]{6}$/i.test(fill)) {
    warnings.push({
      code: "avatar_color_unsupported",
      message:
        "The Grok avatar color was missing or unsupported. A neutral gray placeholder color was used.",
    });
    fill = "#808080";
  }
  // Match the source's light-theme coat while retaining the original identity color.
  const sourceColor = fill;
  fill = LIGHT_COATS[fill.toUpperCase()] ?? fill;
  const geometry =
    shape === "hex"
      ? `<path d="${HEX_HEAD}" fill="${fill}"/><path d="${HEX_EYE_1}" fill="#FFFFFF"/><path d="${HEX_EYE_2}" fill="#FFFFFF"/>`
      : (appMark ??
        `<circle cx="114" cy="114" r="110" fill="${fill}"/><circle cx="80" cy="100" r="12" fill="#171717"/><circle cx="148" cy="100" r="12" fill="#171717"/>`);
  return {
    svg: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${appMark ? "-15 -15 259 259" : "-9.94 -9.94 248.41 248.41"}" data-grok-color="${sourceColor}" color="${fill}">${geometry}</svg>\n`,
    warnings,
  };
}
